const form=document.getElementById("ipForm"),result=document.getElementById("result");form&&form.addEventListener("submit",t=>{t.preventDefault();const a=parseFloat(document.getElementById("income").value)||0,e=parseFloat(document.getElementById("fixed").value)||0,n=parseFloat(document.getElementById("limit").value)||3e5,l=parseFloat(document.getElementById("rate").value)||1;if(e<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Укажите фиксированные взносы больше нуля.</p>';return}const s=a>n?(a-n)*(l/100):0,i=e+s;result.innerHTML=`
      <div class="result-list">
        <div class="item"><span>Фиксированные взносы</span><span class="val">${fmt(e)} ₽</span></div>
        <div class="item"><span>1% с дохода сверх ${fmt(n)} ₽</span><span class="val">${fmt(s)} ₽</span></div>
        <div class="item total"><span>Итого за год</span><span class="val">${fmt(i)} ₽</span></div>
      </div>
    `});function fmt(t){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(t)}
